// Arma la respuesta para el panel: el correo completo o un adjunto.
const pedido = $('Pedido del panel').first().json.body || {};
const m = $input.first().json;

if (m.error) {
  const detalle = typeof m.error === 'string' ? m.error : (m.error.message || JSON.stringify(m.error));
  return [{ json: { ok: false, error: 'No se pudo leer el correo en Microsoft 365: ' + detalle } }];
}

// Historial (Hito 3): una página de correos de la bandeja, del más nuevo al más viejo.
if (pedido.accion === 'listar') {
  const correos = (m.value || []).map(x => {
    const de = (x.from && x.from.emailAddress) || {};
    return {
      id: x.id,
      de: de.name ? `${de.name} <${de.address}>` : (de.address || ''),
      asunto: x.subject || '',
      fecha: x.receivedDateTime || '',
      texto: (x.body && x.body.content) || ''
    };
  });
  return [{ json: { ok: true, correos } }];
}

if (pedido.accion === 'adjunto') {
  return [{ json: { ok: true, nombre: m.name || 'adjunto', tipo: m.contentType || '', tamano: m.size || 0, datos: m.contentBytes || '' } }];
}

const persona = p => (p && p.emailAddress) ? { nombre: p.emailAddress.name || '', correo: p.emailAddress.address || '' } : null;
const escapar = t => String(t || '').replace(/[&<>]/g, c => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;' }[c]));
const cuerpo = m.body || {};

// Solo archivos (no correos adjuntos). Los bytes van para las imágenes del cuerpo y, si se pide copia, para todos.
const adjuntos = (m.attachments || [])
  .filter(a => a['@odata.type'] === '#microsoft.graph.fileAttachment')
  .map(a => ({
    id: a.id,
    nombre: a.name || 'adjunto',
    tipo: a.contentType || '',
    tamano: a.size || 0,
    inline: Boolean(a.isInline),
    contentId: a.contentId || '',
    datos: (a.isInline || pedido.incluir_adjuntos) ? (a.contentBytes || '') : ''
  }));

return [{
  json: {
    ok: true,
    asunto: m.subject || '',
    de: persona(m.from),
    para: (m.toRecipients || []).map(persona).filter(Boolean),
    cc: (m.ccRecipients || []).map(persona).filter(Boolean),
    fecha: m.receivedDateTime || '',
    html: cuerpo.contentType === 'html' ? (cuerpo.content || '') : '<pre style="white-space:pre-wrap">' + escapar(cuerpo.content) + '</pre>',
    adjuntos
  }
}];
